describe('Virtual Scroll List Performance with 10,000 Rows', () => {
  beforeEach(() => {
    cy.visit('/virtual-scroll-list');
  });

  it('should handle 10,000 rows with no lag and display all items', () => {
    // Setup: Create 10,000 mock list items
    for (let i = 1; i <= 10000; i++) {
      cy.get('[data-testid="list-item-container"]').append(`
        <li data-testid="list-item-${i}" class="list-item">
          Item ${i}
        </li>
      `);
    }

    // Verify all items are visible
    cy.get('[data-testid="list-item-container"]').should('have.length.greaterThan', 10000);

    // Verify scrollbar is present
    cy.get('[data-testid="scroll-bar"]').should('be.visible');

    // Verify first item is visible
    cy.get('[data-testid="list-item-1"]').should('be.visible');

    // Verify last item is visible
    cy.get('[data-testid="list-item-10000"]').should('be.visible');

    // Verify virtual scroll is enabled
    cy.get('[data-testid="virtual-scroll-enabled"]').should('be.true');

    // Verify performance - no lag
    cy.get('[data-testid="list-item-container"]').then(($container) => {
      const scrollHeight = $container.scrollHeight;
      const clientHeight = $container.clientHeight;
      expect(scrollHeight).to.be.greaterThan(clientHeight);
    });

    // Verify lazy loading works
    cy.get('[data-testid="list-item-10001"]').should('be.visible');
  });

  it('should handle scrolling to the bottom without performance issues', () => {
    // Setup: Create 10,000 mock list items
    for (let i = 1; i <= 10000; i++) {
      cy.get('[data-testid="list-item-container"]').append(`
        <li data-testid="list-item-${i}" class="list-item">
          Item ${i}
        </li>
      `);
    }

    // Scroll to the bottom
    cy.get('[data-testid="list-item-container"]').scrollTo('bottom');

    // Verify last item is visible
    cy.get('[data-testid="list-item-10000"]').should('be.visible');

    // Verify no lag during scroll
    cy.get('[data-testid="list-item-container"]').then(($container) => {
      const scrollHeight = $container.scrollHeight;
      const clientHeight = $container.clientHeight;
      expect(scrollHeight).to.be.greaterThan(clientHeight);
    });

    // Verify virtual scroll is still enabled
    cy.get('[data-testid="virtual-scroll-enabled"]').should('be.true');
  });
});
